actor ImageCache {
    private enum Entry { case ready(UIImage), loading(Task<UIImage, Error>) }
    private var entries: [URL: Entry] = [:]

    func image(for url: URL) async throws -> UIImage {
        if let entry = entries[url] {
            switch entry {
            case .ready(let image): return image
            case .loading(let task): return try await task.value   // join existing work
            }
        }
        let task = Task { try await download(url) }
        entries[url] = .loading(task)          // mark BEFORE awaiting
        do {
            let image = try await task.value
            entries[url] = .ready(image)
            return image
        } catch {
            entries[url] = nil
            throw error
        }
    }
}
